!> Wraps `cdotu` as a subroutine.
!
! @param {integer} N - number of indexed elements
! @param {Array<complex>} cx - first input array
! @param {integer} incx - `cx` stride length
! @param {Array<complex>} cy - second input array
! @param {integer} incy - `cy` stride length
! @param {complex} dot - output variable reference
!<
subroutine cdotusub( N, cx, incx, cy, incy, dot )
  implicit none
  ! ..
  ! External functions:
  interface
    complex function cdotu( N, cx, incx, cy, incy )
      complex :: cx(*), cy(*)
      integer :: incx, incy, N
    end function cdotu
  end interface
  ! ..
  ! Scalar arguments:
  integer :: incx, incy, N
  complex :: dot
  ! ..
  ! Array arguments:
  complex :: cx(*), cy(*)
  ! ..
  ! Find the dot product:
  dot = cdotu( N, cx, incx, cy, incy )
  return
end subroutine cdotusub